<?php class HomeController{function index(){require_once __DIR__.'/../models/Activity.php';require_once __DIR__.'/../models/Review.php';$activities=array_slice(Activity::all(),0,6);$categories=Activity::categories();$reviews=Review::approved();view('home/index',compact('activities','categories','reviews'));}function contact(){if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();require_once __DIR__.'/../models/Contact.php';if(!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)||empty(trim($_POST['message']??'')))$error='Merci de vérifier les informations saisies.';else{Contact::create($_POST);flash('success','Votre message a bien été envoyé.');redirect('/contact');}}view('home/contact',compact('error'));}}